-- 조달 품목. instructor_id 는 이메일로 찾는다. AUTO_INCREMENT 값을 가정하면
-- 기존 데이터가 있는 DB 에서 엉뚱한 공급기업에 품목이 붙는다.
--
-- 중복 방지를 파생 테이블 NOT EXISTS 로 감싼 이유 — MariaDB 는 INSERT ... SELECT 의
-- 서브쿼리에서 대상 테이블(courses)을 직접 참조하지 못한다(에러 1093). 한 단계
-- 감싸면 통과한다. courses(instructor_id, title) 에 UNIQUE 를 두고 INSERT IGNORE
-- 로 가면 의도가 더 분명하지만, 그건 init-db 스키마 변경이라 별도 작업이다.
--
-- 누적 성과지표 컬럼을 전부 0 으로 적어 넣는다. 기본값에 기대지 않는다 —
-- 실행 중인 DB 의 courses 는 01_init.sql 이 아니라 Hibernate ddl-auto 가
-- 만든 것이라 evaluated_count 같은 NOT NULL 컬럼에 DEFAULT 가 없다.
-- 비워 두면 INSERT 가 1364 로 거부되고, 금액 컬럼은 NULL 로 들어가
-- 첫 성과 평가에서 NPE 가 난다(Course.applyPerformance 에 널 가드가 없다).
INSERT INTO courses (title, description, category, price, instructor_id, instructor_name, contract_end, enrollment_count, status, total_delivered_qty, total_defect_qty, evaluated_count, on_time_count, total_estimated_amount, total_actual_amount, created_at, updated_at)
SELECT '강관파일, 웰텍, WEL-GRPF-SP-1219-22, Φ1219×22mm', '공급업체명: 웰텍(주) | 공급업체소재지: 강원특별자치도 횡성군 | 기업구분: 중소기업 | 품명: 스틸파일 | 세부품명: 강관파일 | 품목명: 강관파일, 웰텍, WEL-GRPF-SP-1219-22, Φ1219×22mm | 물품식별번호: 25175347 | 단위: KG | 공급지역: 전지역(도서지역 제외) | 납품일수: 90일 | 납품장소: 수요기관 지정장소 | 인도조건: 납품장소차상도 | 인증정보: 우수조달물품, G-PASS기업, G-PASS기업(B등급) | 우수제품여부: Y | MAS여부: N | 계약기간: 20260311~20260413 | 쇼핑몰등록일자: 20260311', 'MOBILE', 1704, u.id, '웰텍(주)', '2026-04-13', 0, 'ACTIVE', 0, 0, 0, 0, 0, 0, NOW(6), NOW(6)
  FROM users u WHERE u.email = 'supplier01@procurix.local'
   AND NOT EXISTS (SELECT 1 FROM (SELECT 1) t WHERE EXISTS (SELECT 1 FROM courses c WHERE c.title = '강관파일, 웰텍, WEL-GRPF-SP-1219-22, Φ1219×22mm' AND c.instructor_id = u.id));
